export type MovieboxItem = {
  name?: string;
  title?: string;
  poster_url?: string;
  cover?: string;
  image?: string;
  slug?: string;
  detailPath?: string;
  subject_id?: string | number;
  badge?: string;
  rating?: string | number | null;
  year?: number | string | null;
  type?: string;
  description?: string;
};

export type MovieboxSection = {
  section: string;
  count?: number;
  items: MovieboxItem[];
};

export const MOVIEBOX_API_URL = process.env.MOVIEBOX_API_URL ?? 'http://127.0.0.1:8000';

export const toDisplayTitle = (item: MovieboxItem) => item.name || item.title || 'Untitled';

export const toPosterUrl = (item: MovieboxItem) => {
  const poster = item.poster_url || item.cover || item.image || '';
  return poster || 'https://images.unsplash.com/photo-1516280440614-37939bbacd81?auto=format&fit=crop&w=800&q=80';
};

export async function fetchMoviebox<T>(path: string, params?: Record<string, string | number | undefined>) {
  const url = new URL(path.startsWith('/') ? path : `/${path}`, MOVIEBOX_API_URL);

  Object.entries(params ?? {}).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== '') {
      url.searchParams.set(key, String(value));
    }
  });

  const response = await fetch(url.toString(), {
    headers: {
      Accept: 'application/json',
    },
    cache: 'no-store',
  });

  if (!response.ok) {
    const text = await response.text();
    throw new Error(`Moviebox request failed: ${response.status} ${text}`);
  }

  return (await response.json()) as T;
}
